79 |     }
80 |     // Wrapper for contracts
81 |     function depositForMember(address synth, address member, uint amount) public {
82 |         require((iFACTORY(FACTORY).isSynth(synth)), "Not Synth"); // Only Synths
83 |         getFunds(synth, amount);
84 |         _deposit(synth, member, amount);
85 |     }
86 |     function _deposit(address _synth, address _member, uint _amount) internal {
87 |         mapMemberSynth_lastTime[_member][_synth] = block.timestamp;         // Time of deposit
88 |         mapMemberSynth_deposit[_member][_synth] += _amount;                 // Record deposit
89 |         uint _weight = iUTILS(UTILS()).calcValueInBase(iSYNTH(_synth).TOKEN(), _amount);
90 |         if(iPOOLS(POOLS).isAnchor(iSYNTH(_synth).TOKEN())){
91 |             _weight = iROUTER(ROUTER).getUSDVAmount(_weight);               // Price in USDV
92 |         }
93 |         mapMember_weight[_member] += _weight;                               // Total member weight 
94 |         totalWeight += _weight;                                             // Total weight 
95 |         emit MemberDeposits(_synth, _member, _amount, _weight, totalWeight);
